// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address caller) public {
        vm.prank(caller);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        // owner is the initial owner address(0); owned() must revert for any non-owner caller
        assertTrue(ok == (caller == c.owner()));
    }
}
